import {
  AddOutlined,
  RemoveOutlined,
  ShoppingCartOutlined,
} from "@mui/icons-material";
import { Button, IconButton, Stack } from "@mui/material";
import { Box } from "@mui/system";
import React from "react";
import { useNavigate, Link } from "react-router-dom";
import "./Cart.css";

/* ---------- Helper Functions ---------- */

export const generateCartItemsFrom = (cartData, productsData) => {
  let map = new Map();

  for (let i = 0; i < productsData.length; i++) {
    map.set(productsData[i]["_id"], productsData[i]);
  }

  let cartItems = [];

  cartData.map((x) => {
    let value = map.get(x["productId"]);
    value["quantity"] = x.qty;
    cartItems.push(value);
  });

  return cartItems;
};

export const getTotalCartValue = (items = []) => {
  let value = 0;

  for (let i = 0; i < items.length; i++) {
    value += items[i].quantity * items[i].cost;
  }

  return value;
};

export const getTotalItems = (items = []) => {
  let qty = 0;

  for (let i = 0; i < items.length; i++) {
    qty += items[i].quantity;
  }

  return qty;
};

/* ---------- Item Quantity Component ---------- */

const ItemQuantity = ({ value, handleAdd, handleDelete, productId }) => {
  return (
    <Stack direction="row" alignItems="center">
      <IconButton
        size="small"
        color="primary"
        onClick={() => handleDelete(productId, "-")}
      >
        <RemoveOutlined />
      </IconButton>

      <Box padding="0.5rem" data-testid="item-qty">
        {value}
      </Box>

      <IconButton
        size="small"
        color="primary"
        onClick={() => handleAdd(productId, "handleAdd")}
      >
        <AddOutlined />
      </IconButton>
    </Stack>
  );
};

/* ---------- Display Cart Items ---------- */

function DisplayCartItems(props) {
  const { image, name, cost, quantity, _id: id } = props.items;

  return (
    <Box display="flex" alignItems="flex-start" padding="1rem">
      <Box className="image-container">
        <img src={image} alt={name} width="100%" height="100%" />
      </Box>

      <Box
        display="flex"
        flexDirection="column"
        justifyContent="space-between"
        height="6rem"
        paddingX="1rem"
      >
        <div>{name}</div>

        <Box display="flex" justifyContent="space-between" alignItems="center">
          {!props.isReadOnly ? (
            <ItemQuantity
              value={quantity}
              handleAdd={props.buttonClick}
              handleDelete={props.buttonClick}
              productId={id}
            />
          ) : (
            <Box>Qty:{quantity}</Box>
          )}

          <Box padding="0.5rem" fontWeight="700">
            ${cost}
          </Box>
        </Box>
      </Box>
    </Box>
  );
}

/* ---------- Cart Component ---------- */

const Cart = ({ products, items = [], handleQuantity, isReadOnly }) => {
  const navigate = useNavigate();

  if (!items.length) {
    return (
      <Box className="cart empty">
        <ShoppingCartOutlined className="empty-cart-icon" />
        <Box color="#aaa" textAlign="center">
          Cart is empty. Add more items to the cart to checkout.
        </Box>
      </Box>
    );
  }

  return (
    <>
      <Box className="cart">
        {items.map((values) =>
          isReadOnly ? (
            <DisplayCartItems
              isReadOnly
              items={values}
              buttonClick={handleQuantity}
              key={values["_id"]}
            />
          ) : (
            <DisplayCartItems
              items={values}
              buttonClick={handleQuantity}
              key={values["_id"]}
            />
          )
        )}

        <Box
          padding="1rem"
          display="flex"
          justifyContent="space-between"
          alignItems="center"
        >
          <Box color="#3C3C3C">Order total</Box>

          <Box
            color="#3C3C3C"
            fontWeight="700"
            fontSize="1.5rem"
            data-testid="cart-total"
          >
            ${getTotalCartValue(items)}
          </Box>
        </Box>

        <Box display="flex" justifyContent="flex-end" className="cart-footer">
          {window.location.pathname === "/checkout" ? null : (
            <Button
              color="primary"
              variant="contained"
              onClick={() => navigate("/checkout")}
              className="checkout-btn"
            >
              Checkout
            </Button>
          )}
        </Box>
      </Box>
    </>
  );
};

export default Cart;
